-- Assessment-first admission: Location, CourseOffering, OfferingRate, Material, Assessment
-- and Enrollment plan fields. STAGED + ADDITIVE: no column or row is dropped or rewritten,
-- old Course columns (pricing/availableModes/location/duration/seats) are deprecated in place.
--
-- Part 1 is the DDL (generated by `prisma migrate diff`). Part 2 is the data section.
--
-- DEPLOY NOTE: snapshot production first. Every migrated CourseOffering is created INACTIVE
-- with NO rates (legacy `pricing` was per delivery mode, not per class), so each course shows
-- "enrolment opening soon" publicly until per-class rates are entered in /admin.

-- ============================== Part 1: DDL ==============================

-- CreateEnum
CREATE TYPE "LocationKind" AS ENUM ('PHYSICAL', 'ONLINE');

-- AlterTable
ALTER TABLE "courses" ALTER COLUMN "duration" SET DEFAULT '',
ALTER COLUMN "location" SET DEFAULT '',
ALTER COLUMN "availableModes" SET DEFAULT ARRAY[]::TEXT[],
ALTER COLUMN "pricing" SET DEFAULT '{}';

-- AlterTable
ALTER TABLE "enrollments" ADD COLUMN     "classesPerWeek" INTEGER,
ADD COLUMN     "durationMins" INTEGER,
ADD COLUMN     "locationId" TEXT,
ADD COLUMN     "offeringId" TEXT,
ADD COLUMN     "plannedClasses" INTEGER,
ADD COLUMN     "ratePerClass" INTEGER;

-- AlterTable
ALTER TABLE "instructors" ALTER COLUMN "updatedAt" DROP DEFAULT;

-- CreateTable
CREATE TABLE "locations" (
    "id" TEXT NOT NULL,
    "name" TEXT NOT NULL,
    "slug" TEXT NOT NULL,
    "kind" "LocationKind" NOT NULL DEFAULT 'PHYSICAL',
    "assessmentFee" INTEGER NOT NULL,
    "isActive" BOOLEAN NOT NULL DEFAULT true,
    "order" INTEGER NOT NULL DEFAULT 0,
    "address" TEXT,
    "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updatedAt" TIMESTAMP(3) NOT NULL,

    CONSTRAINT "locations_pkey" PRIMARY KEY ("id")
);

-- CreateTable
CREATE TABLE "course_offerings" (
    "id" TEXT NOT NULL,
    "courseId" TEXT NOT NULL,
    "locationId" TEXT NOT NULL,
    "deliveryModeId" TEXT NOT NULL,
    "classesPerWeekOptions" INTEGER[] DEFAULT ARRAY[1, 2]::INTEGER[],
    "isActive" BOOLEAN NOT NULL DEFAULT false,
    "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updatedAt" TIMESTAMP(3) NOT NULL,

    CONSTRAINT "course_offerings_pkey" PRIMARY KEY ("id")
);

-- CreateTable
CREATE TABLE "offering_rates" (
    "id" TEXT NOT NULL,
    "offeringId" TEXT NOT NULL,
    "durationMins" INTEGER NOT NULL,
    "pricePerClass" INTEGER NOT NULL,
    "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updatedAt" TIMESTAMP(3) NOT NULL,

    CONSTRAINT "offering_rates_pkey" PRIMARY KEY ("id")
);

-- CreateTable
CREATE TABLE "materials" (
    "id" TEXT NOT NULL,
    "courseId" TEXT NOT NULL,
    "name" TEXT NOT NULL,
    "price" INTEGER NOT NULL,
    "required" BOOLEAN NOT NULL DEFAULT false,
    "isActive" BOOLEAN NOT NULL DEFAULT true,
    "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updatedAt" TIMESTAMP(3) NOT NULL,

    CONSTRAINT "materials_pkey" PRIMARY KEY ("id")
);

-- CreateTable
CREATE TABLE "assessments" (
    "id" TEXT NOT NULL,
    "enrollmentId" TEXT NOT NULL,
    "status" TEXT NOT NULL DEFAULT 'requested',
    "arrangement" TEXT NOT NULL,
    "preferredDate" TIMESTAMP(3),
    "preferredTimeBand" TEXT,
    "address" TEXT,
    "landmark" TEXT,
    "scheduledAt" TIMESTAMP(3),
    "assessorId" TEXT,
    "resultLevel" TEXT,
    "resultNotes" TEXT,
    "recommendedOfferingId" TEXT,
    "completedAt" TIMESTAMP(3),
    "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updatedAt" TIMESTAMP(3) NOT NULL,

    CONSTRAINT "assessments_pkey" PRIMARY KEY ("id")
);

